True def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(sum(grid, [])) if any(all(x == v for x in row) for row in grid))
    def spans(n, line):
        out=[]; start=0
        for i in range(n):
            if line(i):
                out.append((start,i)); start=i+1
        out.append((start,n))
        return [(a,b) for a,b in out if a < b]
    rows=spans(h, lambda i: all(x == sep for x in grid[i]))
    cols=spans(w, lambda j: all(grid[i][j] == sep for i in range(h)))
    counts={}
    for row in grid:
        for v in row:
            if v != sep: counts[v]=counts.get(v,0)+1
    bg=max(counts,key=counts.get)
    marker=min((v for v in counts if v != bg), key=lambda v: counts[v])
    return [[1 if sum(grid[r][c] == marker for r in range(a,b) for c in range(x,y)) >= 2 else bg for x,y in cols] for a,b in rows]
